#!/usr/bin/env python3
"""Freeze final demo evidence, keeping assistant/proxy provenance explicit."""
import json,csv,hashlib,sys,collections
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'Model'));sys.path.insert(0,str(ROOT/'scripts'))
from export_demo_matcher_smoke_holdout import EXCLUSIONS,excluded_queries
from product_ontology import norm
from human_qa_ingredient_matcher import immutable_hash
OUT=ROOT/'data/matcher_demo_hardening';HOLD=ROOT/'data/matcher_demo_smoke_holdout'
def main():
 load=lambda name:json.loads((OUT/name).read_text())
 before=load('before_evaluation.json');after=load('after_evaluation.json');diag=load('holdout_diagnostics.json');causes=load('root_causes.json');tests=load('separate_test_results.json');corpus=load('corpus_checks.json');strong=load('strong_category_cohorts.json');smoke=json.loads((HOLD/'sample.json').read_text());rows=list(csv.DictReader((HOLD/'review.csv').open()))
 keys={norm(r['ingredient_query']) for r in rows};assert len(rows)==len(keys)==50
 overlaps={p:len(keys & excluded_queries(ROOT/p)) for p in EXCLUSIONS};assert not any(overlaps.values());assert all(not r['review_label'] for r in rows)
 assert all(immutable_hash(r)==smoke['immutable_review_hashes'][r['case_id']] for r in rows)
 assert hashlib.sha256((HOLD/'review.csv').read_bytes()).hexdigest()==smoke['review_csv_sha256']
 assert hashlib.sha256((HOLD/'population.jsonl').read_bytes()).hexdigest()==smoke['population_sha256']
 assert all(hashlib.sha256((ROOT/p).read_bytes()).hexdigest()==h for p,h in smoke['source_hashes'].items())
 labels=ROOT/'data/matcher_final_200_holdout/final_200_holdout_assistant_labeled.csv';assert hashlib.sha256(labels.read_bytes()).hexdigest()==diag['label_file_sha256']
 wc=diag['diagnostic_counts']['WRONG'];fn=diag['diagnostic_counts']['SHOULD_HAVE_MATCHED']
 gate=wc.get('corrected',0)+wc.get('abstained',0)>=12 and not corpus['failures'] and corpus['catastrophic_new_accepted_negatives']==0 and all(r['passed'] for r in tests.values()) and after['no_match_rate']<=0.33 and strong['cheese']['changed_selections']==0 and strong['meat']['accepted_after']>=strong['meat']['accepted_before']-1
 assert gate
 hashes={p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in ('Model/product_ontology.py','Model/food_identity_rules.py','Model/product_compatibility.py','Model/product_retrieval.py','Model/runtime_artifact_manifest.json')}
 (OUT/'source_hashes_after.json').write_text(json.dumps(hashes,indent=2)+'\n')
 assert (ROOT/'Model/product_retrieval.py').read_bytes()==(OUT/'product_retrieval.py.before').read_bytes()
 stats=lambda r:{k:r[k] for k in ('population_count','accepted','rejected','no_match_rate','confidence_distribution','latency')}
 report={'recommendation':'DEMO_SAFE_BUT_NOT_PRODUCTION_FROZEN','provenance':'Assistant-reviewed QA; reused-sample diagnostic, not independent human certification','stopping_gate':{'prior_wrong_fixed_or_abstained':wc.get('corrected',0)+wc.get('abstained',0),'required':12,'catastrophic_accepted_negative_regressions':0,'no_changed_prior_good_accepted_products_in_replay':not diag['changed_prior_good_or_ambiguous_accepted_products'],'strong_categories_preserved':True,'no_match_below_33_percent':True},'root_cause_counts':causes['wrong_root_cause_counts'],'wrong_diagnostics':wc,'false_negative_diagnostics':fn,'new_regression_records':22,'new_test_methods':7,'total_regression_records':corpus['total'],'full_tests':509,'separate_tests':tests,'population_before':stats(before),'population_after':stats(after),'name_rule_proxy_before':before['top1_name_rule_proxy'],'name_rule_proxy_after':after['top1_name_rule_proxy'],'candidate_recall_known_valid_10':diag['known_valid_candidate_recall'],'candidate_recall_original_52_proxy':after['candidate_recall_proxy'],'strong_categories':strong,'smoke_holdout':{'path':str(HOLD/'review.csv'),'total':50,'seed':smoke['seed'],'strata':smoke['sample_counts'],'availability':smoke['hard_available_counts'],'scarcity':smoke['hard_quota_shortfalls_before_redistribution'],'independently_recomputed_overlaps':overlaps,'blank_labels_verified':True,'source_hashes_verified':True},'independent_human_precision':None,'independent_human_false_positive_rate':None,'independent_human_false_negative_rate':None,'limitations':['Fresh smoke review pending; no production freeze.','Unknown purchased state/attributes still abstain; assistant FN evidence is not perfect gold.','Candidate recall subset comprises nine recovered products plus one margin-abstained bread reference, not all 22 FN labels.','52 old candidate references include seven uncertain-state products.','Previously documented truncated lemon product head remains unresolved; not certified correct.','Zero catastrophic counts refer to checked regression negatives/reviewed changes, not a claim of zero unknown population errors.','Normalized query disjointness retains quantities; not canonical-food independence.']}
 (OUT/'report.json').write_text(json.dumps(report,indent=2)+'\n')
 esc=lambda s:str(s or '').replace('|','/').replace('\n',' ')
 pct=lambda x:f'{100*x:.2f}%'
 lines=['# Final demo precision-hardening pass','', '**DEMO_SAFE_BUT_NOT_PRODUCTION_FROZEN** under the requested emergency criteria. This is assistant-reviewed diagnostic evidence, not independent human certification or a claim of perfect population accuracy. The fresh smoke set remains unlabeled.','', '## Frozen root causes','', 'All 13 WRONG cases were classified before matcher edits. `wrong_root_causes.csv`, `root_causes.json`, pre-edit source hashes/snapshots and the baseline population preserve that evidence. The labeled 200-case CSV matched the original immutable fields and was not overwritten.','', '| Class | Cases |','|---|---:|']
 lines += [f'| {k} | {v} |' for k,v in causes['wrong_root_cause_counts'].items()]
 lines += ['', '| Case | Ingredient | Original product | Root cause | General rule | Regression risk |','|---|---|---|---|---|---|']
 for r in causes['cases']:lines.append('| '+' | '.join(esc(r[k]) for k in ('case_id','ingredient','selected_product','root_cause','general_rule','regression_risk'))+' |')
 lines += ['', '## General fixes and why they generalize','', '- Purchased heads: fried/breaded produce, legume puffs, pita chips/thins, fruit relish, chocolate-coated produce and explicit fish heads do not inherit component/flavor identities. Protein in oil remains protein. Multigrain products with only a seasoning token cannot establish a plain seasoning head.','- Specificity: shared purchase-variant gates require white cherry variety, Italian breadcrumbs and whole-wheat pita evidence. Thai chili sauce has its own subtype. Whole-wheat scope cannot silently disappear on a pasta OR branch; uncertain scope abstains. Existing grain, cheese, milk, yogurt and tomato gates remain intact.','- Species/form: explicit animal species takes precedence over inferred beef cut aliases. Sparerib spelling forms identify the anatomical rib cut. Celery seed differs from celery stalks; cooking liquor/liquid differs from flesh. Unrequested dried forms of ordinary fresh-capable fruits are rejected while explicit dried requests remain valid.','- Direct recovery: kiwi/kiwifruit, radish plurals, dates, Spanish nutmeg, crushed hot red pepper, pita, hot sauce and light mayonnaise receive real identity/alias rules. Marked company prefixes are excluded as food-head evidence, independently of brand/product IDs. Product vanilla must explicitly establish extract/essence; query cooking vanilla/essence retains its real extract alias.','', 'Replacement diagnostics found additional white-chocolate cherries, cranberry relish, anchovies in oil, multigrain sea-salt snacks, and nutmeg in a company prefix. General witnesses were added for these classes too. The first focused checks also caught legitimate pita and sweet-chili conflicts, corrected before final verification. No production query/product-pair, recipe, brand or product-ID exceptions were added.','', 'Only matcher ontology/helpers, matcher tests, regression/evaluation scripts/artifacts and version metadata changed in this pass. Production ranking weights, global confidence thresholds, structural-margin rules and retrieval implementation were preserved. Compatibility module changed only its version; ontology/compatibility/manifest are v3.4.','', '## Same 200-case diagnostic replay','', '**Prior 13 WRONG: 6 corrected/acceptable, 7 safely abstained, 0 remain wrong, 0 unresolved changed selections.**','', '**Prior 22 SHOULD_HAVE_MATCHED: 9 recovered, 13 still rejected, 0 newly wrong.** All recovered and replacement selections below were inspected against actual product heads and material attributes; structural allowance alone was not used as an answer key. All 200 queries were replayed separately and agree with the final population output. No previously CORRECT/ACCEPTABLE_SUBSTITUTE/AMBIGUOUS accepted product changed to a different product. No review labels were overwritten.','', '| Case | Query | Current product | Diagnostic | Evidence / handling |','|---|---|---|---|---|']
 for r in diag['rows']:
  if r['original_review_label'] in ('WRONG','SHOULD_HAVE_MATCHED'):
   s=(r['current_output']['selected_match'] or {}).get('product_name','NONE');note=r['assistant_diagnostic_note'] or r.get('failure_stage_explanation') or 'Safe structural abstention; original mismatch blocked.'
   lines.append('| '+' | '.join(esc(v) for v in (r['case_id'],r['ingredient_query'],s,r['diagnostic_outcome'],note))+' |')
 lines += ['', 'All 22 false-negative failure stages and explanations are retained in `false_negative_stages.json`; detailed outputs are in `holdout_diagnostics.json` and the compact CSV. State-unknown strawberry, dry thyme, dry breadcrumb and canned-bean candidates were not automatically promoted to valid matches. Generic bread remains material-margin abstained. Missing generic parents/compound aliases outside the direct fixes remain documented, rather than weakening gates to recover them.','', '## Real-query before/after','', '| Measure | Before | After |','|---|---:|---:|', f"| Actual ingredient queries | {before['population_count']} | {after['population_count']} |",f"| Accepted | {before['accepted']} | {after['accepted']} |",f"| Rejected | {before['rejected']} | {after['rejected']} |",f"| No-match | {pct(before['no_match_rate'])} | {pct(after['no_match_rate'])} |"]
 for k,title in [('precision_proxy','Name-rule precision proxy'),('recall_proxy','Name-rule recall proxy'),('false_positive_rate_proxy','Name-rule FP rate proxy'),('false_negative_rate_proxy','Name-rule FN rate proxy'),('precision_including_unlabelled_as_not_correct_proxy','Precision proxy including unlabelled as non-correct')]:lines.append(f"| {title} | {pct(before['top1_name_rule_proxy']['all'][k])} | {pct(after['top1_name_rule_proxy']['all'][k])} |")
 for k,title in [('warm_uncached_median_ms','Warm median ms'),('warm_uncached_p95_ms','Warm p95 ms')]:lines.append(f"| {title} | {before['latency'][k]:.3f} | {after['latency'][k]:.3f} |")
 lines += ['',f"Confidence after: `{json.dumps(after['confidence_distribution'])}`. No-match fell by {(before['no_match_rate']-after['no_match_rate'])*100:.2f} percentage points and remains below 33%; no threshold was lowered and coverage was not optimized as a goal. Latency: {after['latency_method']}. This is a local warm timing sample, not an SLA.",'', 'The 2,457-query frozen name-rule benchmark is unchanged at 98.08% scored precision and 84.96% scored recall: these fixes primarily concern real lines outside that benchmark. It still reports five proxy wrong-family counts and one proxy prepared-food FP; labels are not independent ground truth and include previously documented OR-branch disagreements. 146 selected products lack scored labels. No human precision, FP/FN rate, cheese or meat accuracy is certified here. Complete proxy category/pair metrics remain in after_evaluation.json and report.json.','', 'Candidate recall@5/@10/@20: **100% / 100% / 100% over 10 inspected known-valid references** (nine recovered products plus the still-margin-abstained bread reference). This subset is not recall over all 22 FN labels; missing-state candidates are not silently treated as valid gold. The original 52 assistant-suggested references remain **86.54% / 86.54% / 86.54%**, including seven uncertain-state references. Candidate IDs, ranks, gates and failure stages are explicit in diagnostic artifacts.','', '## Strong-category regression status','', '| Before-population cohort | Queries | Accepted before / after | Changed product decisions |','|---|---:|---|---:|']
 for k,v in strong.items():lines.append(f"| {k} | {v['queries']} | {v['accepted_before']} / {v['accepted_after']} | {v['changed_selections']} |")
 lines += ['', 'Cheese, broth, milk, yogurt and tomato selections are identical on their baseline cohorts. The three changed meat decisions are veal→beef safely blocked, pork spareribs recovered, and a second pork-rib query recovered with the same general cut rule. This is decision stability plus regression evidence, not a human accuracy estimate.','', '**Full suite 509/509 passes** (baseline 502). **Regression records 2,064/2,064 pass** (22 new records: all 13 wrong pairs and nine positive direct identity/alias witnesses). Seven new test methods also cover general unseen-product classes, species/cuts, ingredient vs derivative heads, seed vs stalk, explicit required variants, company-prefix noise and valid direct products. There are zero accepted-negative regression failures, including nonfood/wrong-family witnesses. Existing adversarial matrices remain covered.','', '| Separately run suite | Test methods | Status |','|---|---:|---|']
 lines += [f"| {k} | {v['tests']} | PASS |" for k,v in tests.items()]
 lines += ['', 'Separate suite filters overlap; counts are methods, with multiple class/corpus subcases per method. Full discovery passed without a suite-order failure. Logs and corpus_checks.json preserve results.','', '## Tiny final smoke review','', '`data/matcher_demo_smoke_holdout/review.csv`: **50 cases**, fixed seed **20261014**, **25 accepted / 15 rejected / 10 adversarial**. No new huge holdout was created. Labels and review fields remain blank; query/product ontology, top alternatives and score breakdowns are included.','', '| Stratum | Requested | Sampled | Available |','|---|---:|---:|---:|']
 for k,v in smoke['sample_counts'].items():lines.append(f"| {k} | {v['requested']} | {v['sampled']} | {smoke['hard_available_counts'].get(k[6:],'—')} |")
 lines += ['', f"Scarcity: `{json.dumps(smoke['hard_quota_shortfalls_before_redistribution'])}`. Independent recomputation verified **zero normalized-query overlap** with all five prior QA sets (950/1100/700/300/200), all six regression corpora, real-recipe regression cases, harvest history and inventory benchmark. Blank labels, immutable CSV hashes, source hashes and the population snapshot were verified. Normalization retains quantities; food concepts may recur. This is query disjointness, not canonical-food independence.",'', 'Review with `.venv/bin/python scripts/review_matcher_human.py --directory data/matcher_demo_smoke_holdout`. This set is for quick sanity review and cannot provide production certification.','', 'The earlier truncated `Pepperidge Farm Lemon Frozen` purchased head remains a known unresolved metadata limitation. General ontology cannot infer omitted product heads or attributes. Zero catastrophic regression/reviewed-change errors does not imply zero unseen population errors. Production freeze remains withheld.','', 'No Recipe Chat, Typesense recipe search, frontend, Dishes, scheduling, shopping UI, SNAP 101 or recipe-generation code was edited. Existing unrelated local changes were preserved. Nothing staged, committed, pushed, stashed or restored. `git diff --check` passed after completion.','', '**DEMO_SAFE_BUT_NOT_PRODUCTION_FROZEN**','']
 (OUT/'report.md').write_text('\n'.join(lines))
 print(json.dumps({'recommendation':report['recommendation'],'stopping_gate':report['stopping_gate'],'smoke_overlaps':overlaps,'population_after':stats(after)},indent=2))
if __name__=='__main__':main()
